import React, { useState } from 'react';

// Official Sri Sumangala College Panadura Crest (Authentic Crest from srisumangalacollege.lk)
export const SSC_CREST_SRC = '/crest.png';

export const SSC_LOGO_BASE64 =
  'data:image/png;base64,';

interface SSCLogoProps {
  className?: string;
  size?: number;
}

export function SSCLogo({ className = 'w-12 h-12', size }: SSCLogoProps) {
  const [imgSrc, setImgSrc] = useState<string>(SSC_CREST_SRC);

  return (
    <img
      src={imgSrc}
      onError={() => {
        if (imgSrc !== SSC_LOGO_BASE64) {
          setImgSrc(SSC_LOGO_BASE64);
        }
      }}
      alt="Sri Sumangala College Crest"
      className={`${className} object-contain shrink-0`}
      style={size ? { width: size, height: 'auto' } : undefined}
      loading="eager"
    />
  );
}
